import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam and cam.get('walls'):
        sides=[[],[]]
        for b,d in cam['walls']:
            a=math.radians(b+h)
            s=-d*math.cos(a)
            y=d*math.sin(a)
            if s>0.5:
                sides[0 if y<0 else 1].append((s,y))
        vals=[]
        for side in sides:
            pts=sorted(side,key=lambda p:abs(p[0]-4.0))[:3]
            if pts:
                vals.append(sum(p[1] for p in pts)/len(pts))
        if len(vals)==2:
            center=sum(vals)/2
            desired=math.degrees(math.atan(3.65*2*center/16))
    desired=max(-28,min(28,desired))
    steer=max(-34,min(34,0.75*h+2.0*(h-desired)))
    return (steer,-0.8,-23)

